andValueError:"قيمة أمر غير صالحة.",totalCommands:"المجموع: حتى {count} أوامر",fillFieldsError:"القالب والأصل والهدف مطلوبون.",coordCommandMismatchError:"عدم تطابق بين مجموعات الإحداثيات ومجموعات الأوامر (تحقق من ';').",setArrivalDateError:"حدد تاريخ الوصول.",setIntervalError:"حدد بداية ونهاية الفترة.",modelLabel:"قالب",originsLabel:"الأصول",targetsLabel:"الأهداف",commandsLabel:"الأوامر",upTo:"حتى",dateLabel:"التاريخ",intervalLabel:"فترة",removeButton:"إزالة", discordInvite: `للحصول على مفتاح الوصول أو إضافة خوادم: ${discordIconSVG} discord <b><i>_shadow013</i></b>`,
            checkingKey: "جاري التحقق من المفتاح...",
